// A Tijuca passou a fazer parte da Zona Norte: o quiz da Zona Norte tem 10 perguntas, 5 da Zona Norte e 5 da Tijuca.
// As demais perguntas ficam guardadas em PARTIU_DATA.quizzesReserva['zona-norte'] (não são usadas no jogo).
(() => {
  const D = window.PARTIU_DATA, Q = D.quizzes;
  const ficam = ['norte1', 'norte3', 'norte4', 'norte7', 'norte10', 'tij1', 'tij2', 'tij3', 'tij5', 'tij10'];
  const todas = Q['zona-norte'].perguntas.concat(Q.tijuca.perguntas);
  Q['zona-norte'].perguntas = ficam.map(id => todas.find(q => q.id === id));
  D.quizzesReserva = { 'zona-norte': todas.filter(q => !ficam.includes(q.id)) };
  delete Q.tijuca;
})();
